from pathlib import Path
import base64
import sys

if len(sys.argv) != 2:
    raise SystemExit("Usage: apply_psp_live_flogb_v0_5_7c.py <ppsspp_repo>")

repo = Path(sys.argv[1]).resolve()

def require(rel):
    p = repo / rel
    if not p.exists():
        raise SystemExit(f"Missing expected path: {rel}")
    return p

def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly 1 occurrence, found {count}")
    return text.replace(old, new, 1)

def replace_between(text, start, end, replacement, label):
    a = text.find(start)
    if a < 0:
        raise SystemExit(f"{label}: start marker missing")
    b = text.find(end, a + len(start))
    if b < 0:
        raise SystemExit(f"{label}: end marker missing")
    return text[:a] + replacement + text[b:]

debug = require("UI/DebugOverlay.cpp")
info = require("PSP_LIVE_FLOGB_BUILD_INFO.txt")
s = debug.read_text(encoding="utf-8")

for marker in (
    "WINNER ROYAL V0.5.7B",
    "GetSCBDWinnerRoyalTexture",
    "winner_victory.png",
    "winner_pick.png",
    "winner_locked.png",
    "winner_timeout.png",
    "SCBD_RUNTIME_DIAGNOSTIC_VISIBLE = false",
    "DrawSCBDMatchTop5HUD",
    "SCBDVirtualInput::Process();",
):
    if marker not in s:
        raise SystemExit(f"V0.5.7C prerequisite missing: {marker}")

asset_dir = repo / "assets/scbd/winner_asset_v057c"
asset_dir.mkdir(parents=True, exist_ok=True)

ASSETS = {
    "victory_intro.png": "",
    "pick_phase.png": "",
    "locked_in.png": "",
    "timeout.png": "",
}

for name, encoded in ASSETS.items():
    data = base64.b64decode(encoded)
    path = asset_dir / name
    path.write_bytes(data)
    if path.stat().st_size < 100000:
        raise SystemExit(f"V0.5.7C asset unexpectedly small: {name}")

RENDERER_B64 = ""
renderer = base64.b64decode(RENDERER_B64).decode("utf-8")

s = replace_between(
    s,
    "static Draw::Texture *g_scbdWinnerRoyalTextures[4]",
    "static void DrawSCBDBoneMapper(",
    renderer + "\n\n",
    "replace V0.5.7B code-painted Royal renderer with V0.5.7C production-asset renderer",
)

s = replace_once(
    s,
    "WINNER ROYAL V0.5.7B | Web Winner V5 van la fallback LIVE",
    "WINNER ASSET V0.5.7C | approved production asset pack",
    "rename Winner lab for asset integration",
)

debug.write_text(s, encoding="utf-8")

final = debug.read_text(encoding="utf-8")
required = (
    "GetSCBDWinnerAssetTexture",
    "winner_asset_v057c/victory_intro.png",
    "winner_asset_v057c/pick_phase.png",
    "winner_asset_v057c/locked_in.png",
    "winner_asset_v057c/timeout.png",
    "DrawSCBDPickRosterPortraits",
    "DrawSCBDLockedRosterPortraits",
    "DrawSCBDCharacterAtlasOnly",
    "SCBDWinnerFormatScore",
    "WINNER ASSET V0.5.7C",
    "SCBD_RUNTIME_DIAGNOSTIC_VISIBLE = false",
    "SCBDVirtualInput::Process();",
    "DrawSCBDMatchTop5HUD",
)
for marker in required:
    if marker not in final:
        raise SystemExit(f"V0.5.7C generated source missing marker: {marker}")

for forbidden in (
    "g_scbdWinnerRoyalTextures[4]",
    "GetSCBDWinnerRoyalTexture",
):
    if forbidden in final:
        raise SystemExit(f"V0.5.7C old V0.5.7B renderer survived: {forbidden}")

with info.open("a", encoding="utf-8") as f:
    f.write(
        "\nPSP Live FloGB V0.5.7C Winner Asset Integration Pass 1\n"
        "Approved production asset pack is now drawn directly in native winner states\n"
        "Victory Intro: production crown/laurel/emerald panel + dynamic P1/P2 winner text\n"
        "Pick Phase: production frame + clean username/team/score fields + native timer + 28 live portraits\n"
        "Locked In: production frame + live selected portrait + dynamic character/picker/team + selected roster highlight\n"
        "Timeout: production TIME OUT / GAME RANDOM art only; APK never fabricates a random result\n"
        "Input Core V1, Top5 HUD, tracker and random ownership remain unchanged\n"
    )

print("PSP Live FloGB V0.5.7C Winner Asset Integration Pass 1 patch applied successfully.")
